/*
https://leetcode.com/problems/minimum-window-substring/description/
*/

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <numeric>
#include <cstdlib>
#include <ctime>
using namespace std;

// =======================
// Solution Class (Empty)
// =======================
class Solution {
public:
    
    string minWindow(string s, string t) {
        unordered_map<char, int> targetMap;
        for(char c: t){
            targetMap[c]++;
        }

        int left=0, right=0;
        int count=0, minLengthFound = s.size(), targetLength = t.size();
        // For ans generation at the end
        /*
        ans = s.substr(left, right-left) copies a substring many times

        This creates lots of temporary strings during the sliding window.
        If your string is length 100k, you may be making hundreds of substr copies.
        */
        int startIndex=-1;

        while(left<=right){
            if(count == targetLength || right == s.size()){
                if(count == targetLength && right-left <= minLengthFound){
                    minLengthFound = right-left;
                    // ans = getSubStr(s, left, right);
                    // ans = s.substr(left, right-left);
                    startIndex = left;
                }

                if(targetMap.count(s[left]) == 1) {
                    if(targetMap[s[left]] == 0){
                        count--;
                    }
                    targetMap[s[left]]++;
                }
                left++;
            } else if(right < s.size()) {
                if(targetMap.count(s[right]) == 1){
                    if(targetMap[s[right]] > 0){
                        count++;
                    }
                    targetMap[s[right]]--;
                }
                right++;
            }
            // cout << s << "-->" << left << "," << right << "<" << minLengthFound << "-->" << count << "-->" << ans << endl;
            // for(auto m:targetMap){
            //     cout << m.first << ":" << m.second << "," << endl;
            // }
            // cout << endl;
        }

        if(startIndex != -1) {
            return s.substr(startIndex, minLengthFound);
        } else {
            return "";
        }
    }
};

// =======================
// Reference Implementation
// =======================
string expected_minWindow(const string &s, const string &t) {
    if (t.empty() || s.empty()) return "";

    vector<int> tCount(128, 0), window(128, 0);
    for (char c : t) tCount[c]++;

    int have = 0, need = 0;
    for (int c = 0; c < 128; ++c)
        if (tCount[c] > 0) need++;

    int left = 0, minLen = s.size() + 1, start = 0;
    for (int right = 0; right < (int)s.size(); ++right) {
        char c = s[right];
        window[c]++;
        if (window[c] == tCount[c] && tCount[c] > 0)
            have++;

        while (have == need) {
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                start = left;
            }
            char lc = s[left];
            window[lc]--;
            if (window[lc] < tCount[lc] && tCount[lc] > 0)
                have--;
            left++;
        }
    }

    if (minLen > (int)s.size()) return "";
    return s.substr(start, minLen);
}

// =======================
// Helper: Print Result
// =======================
void print_result(const string &s, const string &t, const string &expected, const string &got) {
    cout << "s = \"" << s << "\", t = \"" << t << "\"\n";
    cout << "Expected: \"" << expected << "\" | Got: \"" << got << "\" --> ";
    if (expected == got) cout << "✅ PASS\n";
    else cout << "❌ FAIL\n";
    cout << "----------------------------------\n";
}

// =======================
// Random String Generator
// =======================
string random_string(int len) {
    string s;
    for (int i = 0; i < len; ++i)
        s.push_back('A' + rand() % 6); // A-F
    return s;
}

// =======================
// Main Test Harness
// =======================
int main() {
    srand(time(0));
    Solution sol;

    vector<pair<string, string>> tests = {
        {"ADOBECODEBANC", "ABC"},
        {"a", "a"},
        {"a", "aa"},
        {"ABCD", "E"},
        {"", "aAbBcCdDeEfFgGhHiIjJkKlLmMnNoOpPqQrRsStTuUvVwWxXyYzZ"}
    };

    // Add random test cases
    for (int i = 0; i < 5; ++i) {
        string s = random_string(10 + rand() % 10);
        string t = random_string(2 + rand() % 3);
        tests.push_back({s, t});
    }

    cout << "Running " << tests.size() << " test cases...\n";
    cout << "==================================\n";

    for (auto &test : tests) {
        string s = test.first;
        string t = test.second;
        string expected = expected_minWindow(s, t);
        string got = sol.minWindow(s, t);
        print_result(s, t, expected, got);
    }

    return 0;
}